import React, { useState } from 'react';
import styled from 'styled-components';
const Buttt = styled.button`
    background-color: #418d35;
    border-radius: 14px;
    border: none;
    padding: 15px;
    color: white;
    margin: 5px;
`;
const ImageContainer = styled.div`
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    width: 100%;
    max-width: 100%;
`;
const Buttt1 = styled.button`
    background-color: #d42d2d;
    border-radius: 14px;
    border: none;
    padding: 15px;
    color: white;
    margin: 5px;
`;
const InputField = styled.input`
    padding: 10px;
    background-color: #96823b;
    border: none;
    color: #423711 !important;
    -webkit-text-fill-color: #423711;
    border-radius: 14px;
    margin: 5px;
    &:-webkit-autofill {
        -webkit-box-shadow: 0 0 0 30px #96823b inset !important;
        -webkit-text-fill-color: #423711 !important;
    }
    &::placeholder {
        color: #423711;
    }
`;

const Contacts = styled.div`
    background-color: #ffd54f;
    padding: 20px;
    border-radius: 10px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
    width: 220px;
    margin-right: 100px;
`;

const PageWrapper = styled.div`
    height: 80vh;
    display: flex;
    justify-content: center;
    align-items: center;
`;

const Container = styled.div`
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    height: 100%;
    background-color: rgba(255, 255, 255, 0.8);
    padding: 20px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
    border-radius: 10px;
    max-width: 1000px;
    width: 150%;
`;

const Admin_panel = () => {
    const [name, setName] = useState('');
    const [country, setCountry] = useState('');
    const [engine, setEngine] = useState('');
    const [color, setColor] = useState('');
    const [box, setBox] = useState('');
    const [comp, setComp] = useState('');
    const [image, setImage] = useState(null);
    const [fetchedImage, setFetchedImage] = useState(null);
    const handleImageChange = (e) => {
        const file = e.target.files[0];
        const reader = new FileReader();
        reader.onloadend = () => {
            setImage(reader.result);
        };
        if (file) {
            reader.readAsDataURL(file);
        }
    };
    const addPhoto = (e) => {
        e.preventDefault();
        if (image) {
            fetch(`http://localhost:4000/api/cars/${name}/addphoto`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ image }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Зображення успішно завантажено!');
                    } else {
                        alert('Помилка при завантаженні зображення.');
                    }
                })
                .catch((error) => {
                    alert('Сталася помилка: ' + error.message);
                });
        }
    };
    const handleAdd = (e) => {
        e.preventDefault();

        if (name && country && engine && color && box && comp) {
            let car = {
                name: name,
                category: country,
                engines: [engine],
                gearboxes: [box],
                completeSet: [comp],
                color: [color],
                photo: 'data:image/png;base64,',
            };

            fetch('http://localhost:4000/api/cars', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(car),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Автомобіль успішно додано!');
                        setName('');
                        setCountry('');
                        setEngine('');
                        setColor('');
                        setBox('');
                        setComp('');
                    } else {
                        alert('Сталася помилка при додаванні автомобіля.');
                    }
                })
                .catch((error) => {
                    alert('Сталася помилка: ' + error.message);
                });
        } else if (name && !engine && !country && !color && box && !comp) {
            fetch(`http://localhost:4000/api/cars/${name}/add-box`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ box: box }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Коробку успішно додано!');
                        setName('');
                        setBox('');
                    } else {
                        throw new Error('Помилка при додаванні коробки');
                    }
                })
                .catch((error) => {
                    console.error('Сталася помилка:', error);
                });
        } else if (name && !engine && !country && color && !box && !comp) {
            fetch(`http://localhost:4000/api/cars/${name}/add-color`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ color: color }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Колір успішно додано!');
                        setName('');
                        setColor('');
                    } else {
                        throw new Error('Помилка при додаванні коліру');
                    }
                })
                .catch((error) => {
                    console.error('Сталася помилка:', error);
                });
        } else if (name && !engine && !country && !color && !box && comp) {
            fetch(`http://localhost:4000/api/cars/${name}/add-comp`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ comp: comp }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Комплектацію успішно додано!');
                        setName('');
                        setComp('');
                    } else {
                        throw new Error('Помилка при додаванні комплектації');
                    }
                })
                .catch((error) => {
                    console.error('Сталася помилка:', error);
                });
        } else {
            alert('Будь ласка, заповніть необхідні поля.');
        }
    };
    const handleSearch = (e) => {
        if (name && !engine && !country && !color && !box && !comp) {
            e.preventDefault();
            fetch(`http://localhost:4000/api/cars/${name}`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                },
            })
                .then((response) => {
                    if (!response.ok) {
                        throw new Error('Нема такої машини');
                    }
                    return response.json();
                })
                .then((data) => {
                    console.log('Отримані дані:', data);
                    if (Array.isArray(data) && data.length > 0) {
                        setCountry(data[0].category);
                        setName(data[0].name);
                        setBox(data[0].gearboxes[0]);
                        setColor(data[0].color[0]);
                        setEngine(data[0].engines[0]);
                        setComp(data[0].completeSet[0]);
                        if (data[0].photo) {
                            setFetchedImage(data[0].photo);
                        } else {
                            setFetchedImage(null);
                        }
                    } else {
                        alert('Дані відсутні або не повні.');
                    }
                })
                .catch((error) => {
                    alert('Сталася помилка: ' + error.message);
                });
        } else if (name && engine == '=' && !country && !color && !box && comp) {
            fetch(`http://localhost:4000/api/cars/${name}/getEngines`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                },
            })
                .then((response) => {
                    if (!response.ok) {
                        throw new Error('Нема такої машини');
                    }
                    return response.json();
                })
                .then((data) => {
                    alert(JSON.stringify(data));
                });
        }
    };

    const handleDell = (e) => {
        e.preventDefault();
        if (name && !engine && !box && !comp && !color) {
            fetch(`http://localhost:4000/api/cars/${name}`, {
                method: 'DELETE',
                headers: {
                    'Content-Type': 'application/json',
                },
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Автомобіль успішно видалено!');
                        setName('');
                    } else {
                        alert('Сталася помилка при видаленні автомобіля.');
                    }
                })
                .catch((error) => {
                    alert('Сталася помилка: ' + error.message);
                });
        } else if (name && engine && !country && !color && !box && !comp) {
            fetch(`http://localhost:4000/api/cars/${name}/remove-engine`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ engine: engine }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Двигун успішно видалено!');
                        setName('');
                        setEngine('');
                    } else {
                        throw new Error('Помилка при видаленні двигуна');
                    }
                })
                .catch((error) => {
                    console.error('Сталася помилка:', error);
                });
        } else if (name && !engine && !country && !color && box && !comp) {
            fetch(`http://localhost:4000/api/cars/${name}/remove-box`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ box: box }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Коробку успішно видалено!');
                        setName('');
                        setBox('');
                    } else {
                        throw new Error('Помилка при видаленні коробки');
                    }
                })
                .catch((error) => {
                    console.error('Сталася помилка:', error);
                });
        } else if (name && !engine && !country && color && !box && !comp) {
            fetch(`http://localhost:4000/api/cars/${name}/remove-color`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ color: color }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Колір успішно видалено!');
                        setName('');
                        setColor('');
                    } else {
                        throw new Error('Помилка при видаленні Кольору');
                    }
                })
                .catch((error) => {
                    console.error('Сталася помилка:', error);
                });
        } else if (name && !engine && !country && !color && !box && comp) {
            fetch(`http://localhost:4000/api/cars/${name}/remove-comp`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ comp: comp }),
            })
                .then((response) => {
                    if (response.ok) {
                        alert('Комплектацію успішно видалено!');
                        setName('');
                        setComp('');
                    } else {
                        throw new Error('Помилка при видаленні комплектації');
                    }
                })
                .catch((error) => {
                    console.error('Сталася помилка:', error);
                });
        } else {
            alert('Будь ласка, заповніть необхідні поля.');
        }
    };
    return (
        <PageWrapper>
            <Container>
                <Contacts>
                    <form>
                        <div>
                            <InputField
                                type="text"
                                id="Name"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                placeholder="Назва"
                            />
                        </div>
                        <div>
                            <InputField
                                type="text"
                                id="country"
                                value={country}
                                onChange={(e) => setCountry(e.target.value)}
                                placeholder="Категорія"
                            />
                        </div>
                        <div>
                            <InputField
                                type="text"
                                id="engine"
                                value={engine}
                                onChange={(e) => setEngine(e.target.value)}
                                placeholder="Двигун"
                            />
                        </div>
                        <div>
                            <InputField
                                type="text"
                                id="color"
                                value={color}
                                onChange={(e) => setColor(e.target.value)}
                                placeholder="Колір"
                            />
                        </div>
                        <div>
                            <InputField
                                type="text"
                                id="box"
                                value={box}
                                onChange={(e) => setBox(e.target.value)}
                                placeholder="Коробка"
                            />
                        </div>
                        <div>
                            <InputField
                                type="text"
                                id="comp"
                                value={comp}
                                onChange={(e) => setComp(e.target.value)}
                                placeholder="Комплектація"
                            />
                        </div>

                        <div>
                            <Buttt type="button" onClick={handleAdd}>
                                Додати
                            </Buttt>
                            <Buttt1 type="button" onClick={handleDell}>
                                Видалити
                            </Buttt1>
                            <Buttt type="button" onClick={handleSearch}>
                                Знайти
                            </Buttt>
                        </div>
                        <input type="file" onChange={handleImageChange} accept="image/*" lang="uk" />
                        <Buttt type="button" onClick={addPhoto}>
                            Додати фото
                        </Buttt>
                    </form>
                </Contacts>

                <ImageContainer>
                    {fetchedImage && (
                        <div>
                            <h3>Зображення машини:</h3>
                            <img src={fetchedImage} alt="Об'єкт" style={{ width: '100%', height: 'auto' }} />
                        </div>
                    )}
                </ImageContainer>
            </Container>
        </PageWrapper>
    );
};

export { Admin_panel };
